#include <vector>
#include <cstddef>
#include <omp.h>

void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    // Assume A stores an MxN matrix in row-major order.
    // Resize y to the required output size.
    y.resize(M);

    // Parallelize over rows so each thread writes to distinct y[i].
    #pragma omp parallel for
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(M); ++i) {
        double sum = 0.0;
        const size_t row = static_cast<size_t>(i) * N;
        for (size_t j = 0; j < N; ++j) {
            sum += A[row + j] * x[j];
        }
        y[static_cast<size_t>(i)] = sum;
    }
}
